package cn.mop.domain.backup;
import cn.mop.domain.DomainException;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;
class BackupDeviceLeaseStateTest {
 static final UUID TENANT=UUID.fromString("73000000-0000-4000-8000-000000000001"),ASSET=UUID.fromString("73000000-0000-4000-8000-000000000002"),REQUEST=UUID.fromString("73000000-0000-4000-8000-000000000003"),NEXT=UUID.fromString("73000000-0000-4000-8000-000000000004");
 static final Instant AT=Instant.parse("2026-10-21T00:00:00Z");static final Duration LEASE=Duration.ofSeconds(30);
 static BackupDeviceLeaseState state(){return BackupDeviceLeaseState.initial(TENANT,ASSET,REQUEST,"synthetic-worker",AT,LEASE);}
 @Test void explicitIdentityDoesNotGrantAuthority(){var s=state();assertEquals(TENANT,s.tenantId());assertEquals(ASSET,s.assetId());assertEquals(REQUEST,s.requestId());assertEquals(1,s.version());assertEquals(1,s.fencingToken());assertEquals(AT.plus(LEASE),s.leaseUntil());assertEquals(LEASE,s.duration());assertNull(s.releasedAt());assertEquals(BackupDeviceLeaseState.Status.HELD,s.statusAt(AT));assertFalse(s.deviceExecutionAuthorized());assertFalse(s.distributedLockVerified());assertFalse(s.expiredTakeoverAllowed());}
 @Test void exactExpiryAndLaterRemainBlocked(){var s=state();for(var at:new Instant[]{s.leaseUntil(),s.leaseUntil().plusSeconds(1),s.leaseUntil().plus(Duration.ofDays(7))}){assertEquals(BackupDeviceLeaseState.Status.RECONCILIATION_REQUIRED,s.statusAt(at));assertFalse(s.mayCoordinateAt(s.owner(),s.fencingToken(),at));assertThrows(DomainException.class,()->s.next(1,NEXT,"next",at,LEASE));assertThrows(DomainException.class,()->s.renew(1,s.owner(),1,at));assertThrows(DomainException.class,()->s.release(1,s.owner(),1,at));}}
 @Test void passingTimeIsNotAStopReceipt(){var s=state();assertNull(s.releasedAt());assertThrows(DomainException.class,()->s.next(1,NEXT,"next",AT.plusSeconds(1),LEASE));assertEquals(BackupDeviceLeaseState.Status.RECONCILIATION_REQUIRED,s.statusAt(AT.plusSeconds(600)));}
 @Test void renewalRequiresOwnerFenceVersionAndMonotonicTime(){var s=state();var r=s.renew(1,s.owner(),1,AT.plusSeconds(5));assertEquals(2,r.version());assertEquals(1,r.fencingToken());assertEquals(AT.plusSeconds(35),r.leaseUntil());assertEquals(AT.plusSeconds(30),s.leaseUntil());assertEquals(AT.plusSeconds(5),r.observedAt());assertThrows(DomainException.class,()->r.renew(1,r.owner(),1,AT.plusSeconds(6)));assertThrows(DomainException.class,()->r.renew(2,"other",1,AT.plusSeconds(6)));assertThrows(DomainException.class,()->r.renew(2,r.owner(),2,AT.plusSeconds(6)));assertThrows(DomainException.class,()->r.renew(2,r.owner(),1,AT.plusSeconds(4)));}
 @Test void identicalInstantRenewalDoesNotInventHeartbeat(){var s=state();assertSame(s,s.renew(1,s.owner(),1,AT));}
 @Test void releaseThenNextRequestIncreasesFenceAndKeepsOldFacts(){var s=state();var released=s.release(1,s.owner(),1,AT.plusSeconds(2));assertEquals(BackupDeviceLeaseState.Status.RELEASED,released.statusAt(AT.plusSeconds(40)));assertFalse(released.mayCoordinateAt(s.owner(),1,AT.plusSeconds(3)));var next=released.next(2,NEXT,"next-worker",AT.plusSeconds(3),Duration.ofMillis(1));assertEquals(2,next.fencingToken());assertEquals(3,next.version());assertEquals(NEXT,next.requestId());assertEquals("next-worker",next.owner());assertEquals(AT.plusSeconds(3).plusMillis(1),next.leaseUntil());assertFalse(next.mayCoordinateAt(s.owner(),1,AT.plusSeconds(3)));assertEquals(REQUEST,released.requestId());assertEquals(AT.plusSeconds(2),released.releasedAt());}
 @Test void releasedLeaseCannotRenewOrReuseRequest(){var s=state().release(1,"synthetic-worker",1,AT.plusSeconds(2));assertThrows(DomainException.class,()->s.renew(2,s.owner(),1,AT.plusSeconds(3)));assertThrows(DomainException.class,()->s.release(2,s.owner(),1,AT.plusSeconds(3)));assertThrows(DomainException.class,()->s.next(2,REQUEST,"next",AT.plusSeconds(3),LEASE));assertThrows(DomainException.class,()->s.next(2,NEXT,"next",AT.plusSeconds(1),LEASE));}
 @Test void durationIsExplicitWholeMillisecondsWithTechnicalBound(){for(Duration d:new Duration[]{null,Duration.ZERO,Duration.ofMillis(-1),Duration.ofNanos(1),Duration.ofMinutes(5).plusMillis(1)})assertThrows(DomainException.class,()->BackupDeviceLeaseState.initial(TENANT,ASSET,REQUEST,"worker",AT,d));assertEquals(AT.plusMillis(1),BackupDeviceLeaseState.initial(TENANT,ASSET,REQUEST,"worker",AT,Duration.ofMillis(1)).leaseUntil());assertEquals(AT.plusSeconds(300),BackupDeviceLeaseState.initial(TENANT,ASSET,REQUEST,"worker",AT,Duration.ofMinutes(5)).leaseUntil());}
 @Test void invalidIdentitiesAndOwnersReject(){for(String owner:new String[]{null,"","space value","x".repeat(129)})assertThrows(DomainException.class,()->BackupDeviceLeaseState.initial(TENANT,ASSET,REQUEST,owner,AT,LEASE));assertThrows(DomainException.class,()->BackupDeviceLeaseState.initial(null,ASSET,REQUEST,"worker",AT,LEASE));assertThrows(DomainException.class,()->BackupDeviceLeaseState.initial(TENANT,null,REQUEST,"worker",AT,LEASE));assertThrows(DomainException.class,()->BackupDeviceLeaseState.initial(TENANT,ASSET,null,"worker",AT,LEASE));}
 @Test void timePrecisionBoundsAndOverflowReject(){for(Instant at:new Instant[]{null,AT.plusNanos(1),Instant.parse("0000-12-31T23:59:59Z"),Instant.parse("+10000-01-01T00:00:00Z"),Instant.parse("9999-12-31T23:59:59.999Z")})assertThrows(DomainException.class,()->BackupDeviceLeaseState.initial(TENANT,ASSET,REQUEST,"worker",at,LEASE));assertThrows(DomainException.class,()->state().statusAt(AT.minusMillis(1)));assertThrows(DomainException.class,()->state().mayCoordinateAt("worker",1,AT.minusMillis(1)));}

 static BackupDeviceLeaseState.Snapshot raw(long fence,long version,Instant observed,Instant until,Instant released){return new BackupDeviceLeaseState.Snapshot(TENANT,ASSET,REQUEST,"synthetic-worker",fence,version,LEASE,AT,observed,until,released);}
 @Test void validSnapshotsRoundTripWithoutGainingAuthority(){var held=state().renew(1,"synthetic-worker",1,AT.plusSeconds(1));var released=held.release(2,"synthetic-worker",1,AT.plusSeconds(2));var next=released.next(3,NEXT,"next",AT.plusSeconds(3),LEASE);for(var value:new BackupDeviceLeaseState[]{state(),held,released,next}){var restored=BackupDeviceLeaseState.rehydrate(value.snapshot());assertEquals(value.snapshot(),restored.snapshot());assertFalse(restored.distributedLockVerified());assertFalse(restored.deviceExecutionAuthorized());}}
 @Test void nullOrInvalidCounterSnapshotsReject(){assertThrows(DomainException.class,()->BackupDeviceLeaseState.rehydrate(null));for(long[] pair:new long[][]{{0,1},{1,0},{2,1},{2,2},{BackupDeviceLeaseState.MAX_SAFE,BackupDeviceLeaseState.MAX_SAFE},{1,BackupDeviceLeaseState.MAX_SAFE+1}})assertThrows(DomainException.class,()->BackupDeviceLeaseState.rehydrate(raw(pair[0],pair[1],AT,AT.plus(LEASE),null)));}
 @Test void impossibleActiveDeadlineAndObservedTimeReject(){for(var s:new BackupDeviceLeaseState.Snapshot[]{raw(1,1,AT,AT.plusSeconds(29),null),raw(1,1,AT.minusMillis(1),AT.plus(LEASE),null),raw(1,1,AT,AT,null)})assertThrows(DomainException.class,()->BackupDeviceLeaseState.rehydrate(s));}
 @Test void releasedSnapshotRequiresConsistentReleaseAndHistoricalHeartbeat(){for(var s:new BackupDeviceLeaseState.Snapshot[]{raw(1,1,AT,AT.plus(LEASE),AT),raw(1,2,AT.plusSeconds(2),AT.plus(LEASE),AT.plusSeconds(1)),raw(1,2,AT.plusSeconds(2),AT.plusSeconds(40),AT.plusSeconds(2)),raw(1,2,AT.plusSeconds(2),AT.plusSeconds(20),AT.plusSeconds(2))})assertThrows(DomainException.class,()->BackupDeviceLeaseState.rehydrate(s));}
 @Test void safeIntegerRevisionOverflowCannotWrap(){var held=BackupDeviceLeaseState.rehydrate(raw(1,BackupDeviceLeaseState.MAX_SAFE,AT,AT.plus(LEASE),null));assertThrows(DomainException.class,()->held.renew(held.version(),held.owner(),1,AT.plusMillis(1)));assertThrows(DomainException.class,()->held.release(held.version(),held.owner(),1,AT.plusMillis(1)));var released=BackupDeviceLeaseState.rehydrate(raw(1,BackupDeviceLeaseState.MAX_SAFE,AT.plusSeconds(2),AT.plus(LEASE),AT.plusSeconds(2)));assertThrows(DomainException.class,()->released.next(released.version(),NEXT,"next",AT.plusSeconds(3),LEASE));}
 @Test void snapshotObjectsRemainDetachedImmutableFacts(){var original=state();var snapshot=original.snapshot();var renewed=original.renew(1,original.owner(),1,AT.plusMillis(1));assertEquals(snapshot,original.snapshot());assertNotEquals(snapshot,renewed.snapshot());assertEquals(AT,snapshot.acquiredAt());}
}
